SEP = "|"
QUOTE = "\""


def _tokenize(text):
    """Split text into fields, each a list of (text, quoted) pieces.

    Only the unquoted pieces may be split on SEP; the quoted pieces are already
    unescaped (QUOTE QUOTE -> QUOTE).
    """
    fields, field, piece = [], [], ""
    i, n = 0, len(text)
    while i < n:
        ch = text[i]
        if ch == QUOTE:
            if piece:
                field.append((piece, False))
                piece = ""
            i += 1
            quoted = ""
            while True:
                if i >= n:
                    raise ValueError(f"unclosed quote in {text!r}")
                if text[i] == QUOTE:
                    if i + 1 < n and text[i + 1] == QUOTE:
                        quoted += QUOTE
                        i += 2
                        continue
                    i += 1
                    break
                quoted += text[i]
                i += 1
            field.append((quoted, True))
        elif ch == SEP:
            if piece:
                field.append((piece, False))
                piece = ""
            fields.append(field)
            field = []
            i += 1
        else:
            piece += ch
            i += 1
    if piece:
        field.append((piece, False))
    fields.append(field)
    return fields


def _join(pieces):
    """Join pieces, dropping whitespace outside quotes at either end."""
    pieces = list(pieces)
    if pieces and not pieces[0][1]:
        pieces[0] = (pieces[0][0].lstrip(), False)
    if pieces and not pieces[-1][1]:
        pieces[-1] = (pieces[-1][0].rstrip(), False)
    return "".join(p for p, _ in pieces)


def parse_fields(text):
    """Parse a line like name=Ann| note="hi| there" into a dict of strings.

    Fields are separated by SEP. Whitespace around keys and around unquoted values is
    ignored. A value may be wrapped in QUOTE characters; inside quotes, SEP and '='
    are ordinary characters, whitespace is kept, and two QUOTE characters in a row
    stand for one QUOTE character. Empty fields, such as one after a trailing SEP,
    are skipped, so a blank line gives {}. A field without '=', an empty key, a
    quote that is never closed, or a key that appears twice raises ValueError.
    """
    result = {}
    for pieces in _tokenize(text):
        if not any(quoted or p.strip() for p, quoted in pieces):
            continue
        raw = "".join(p if not q else QUOTE + p + QUOTE for p, q in pieces)
        key_pieces, value_pieces, found = [], [], False
        for p, quoted in pieces:
            if found or quoted or "=" not in p:
                (value_pieces if found else key_pieces).append((p, quoted))
                continue
            before, after = p.split("=", 1)
            key_pieces.append((before, False))
            value_pieces.append((after, False))
            found = True
        if not found:
            raise ValueError(f"field without '=': {raw!r}")
        key = _join(key_pieces)
        if not key:
            raise ValueError(f"empty key in {raw!r}")
        if key in result:
            raise ValueError(f"duplicate key {key!r}")
        result[key] = _join(value_pieces)
    return result
