from fractions import Fraction

from .allocate import apportion
from .duration import parse


def bill(entries, rate_per_hour):
    """Charge each person for their time.

    entries is a list of (name, duration) pairs, where duration is text for
    duration.parse(), and rate_per_hour is a whole number of cents per hour.

    Names are matched ignoring case and surrounding spaces. Each person appears once
    in the result, under the first spelling seen (with spaces trimmed), in order of
    first appearance. The total charge is worked out from everyone's exact total
    seconds and rounded to a whole cent only once,
    with exact halves rounded up. It is then divided between people with
    apportion(), in proportion to their seconds. If the total time is zero, everyone
    is charged 0.

    Returns a list of (name, cents) pairs; no entries gives [].
    """
    names = {}  # lower-cased key -> first spelling
    totals = {}  # lower-cased key -> seconds
    for name, text in entries:
        seconds = parse(text)
        name = name.strip()
        key = name.lower()
        if key not in names:
            names[key] = name
            totals[key] = 0
        totals[key] += seconds
    if not names:
        return []
    total_seconds = sum(totals.values())
    if total_seconds == 0:
        return [(names[k], 0) for k in names]
    exact = Fraction(total_seconds * rate_per_hour, 3600)
    charge = int(exact + Fraction(1, 2)) if exact >= 0 else -int(-exact + Fraction(1, 2))
    if exact < 0 and (-exact) % 1 == Fraction(1, 2):
        charge += 1  # exact halves round up (towards +infinity)
    shares = apportion(charge, [totals[k] for k in names])
    return list(zip(names.values(), shares))
