            return True
        if dom_ok is None:
            return dow_ok
        if dow_ok is None:
            return dom_ok
        return dom_ok or dow_ok

    def matches(self, when):
        return (
            when.minute in self.minutes
            and when.hour in self.hours
            and when.month in self.month_set
            and self.day_ok(when.date())
        )

    def next_run(self, after):
        start = after.replace(second=0, microsecond=0) + datetime.timedelta(minutes=1)
        limit = after + _LIMIT
        day = start.date()
        first = True
        while True:
            if day.month not in self.month_set:
                year, month = day.year, day.month + 1
                if month > 12:
                    year, month = year + 1, 1
                day = datetime.date(year, month, 1)
                first = False
                if datetime.datetime.combine(day, datetime.time()) > limit:
                    return None
                continue
            if datetime.datetime.combine(day, datetime.time()) > limit:
                return None
            if self.day_ok(day):
                for h in self.hours:
                    if first and h < start.hour:
                        continue
                    for m in self.minutes:
                        candidate = datetime.datetime.combine(day, datetime.time(h, m))
                        if candidate < start:
                            continue
                        if candidate > limit:
                            return None
                        return candidate
            first = False
            day += datetime.timedelta(days=1)


def matches(expr, when):
    """True if the schedule expr runs at the minute of the datetime when."""
    return _Schedule(expr).matches(when)


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    return _Schedule(expr).next_run(after)
